post_days = {0,2,4,7,9,11,14,16,18,21,23,25,28}
activities = ['Publish' if i in post_days else ('Review & respond' if i % 7 in (5,6) else 'Prepare & engage') for i in range(30)]
tags = {'Education':'#ProfitLane #TruckDispatch #OwnerOperator #LoadPlanning','Industry tips':'#ProfitLane #DispatchTips #TruckDispatch #LoadPlanning','Engagement':'#ProfitLane #TruckDispatch #DispatcherLife','Product concept':'#ProfitLane #DispatchTools #AIassistant #TruckDispatch','Brand awareness':'#ProfitLane #TruckDispatch #SmallBusiness #DispatchTools'}
calendar=[]
for i,(title,category,hook,fmt,msg,caption,cta) in enumerate(ideas):
 calendar.append(dict(day=i+1,date=str(date(2026,11,9)+timedelta(days=i)),activity=activities[i],title=title,category=category,hook=hook,format=fmt,message=msg,caption=caption,hashtags=tags[category],cta=cta))
# Ten scripts correspond to the first ten scheduled posts, in order.
spoken=[
"AI should help your dispatch desk—not take it over. ProfitLane is an AI dispatching assistant in development. The goal is to help independent dispatchers organize load information, review costs and prepare for rate conversations. Your experience and your judgment stay at the center. We are sharing practical load-review ideas as we develop the concept. Follow along, and tell us which part of reviewing a load needs the most support.",
"That load starts before pickup. Count those miles. Here is a fictional example: 100 empty miles to pickup and 500 loaded miles. That is 600 total miles. If the offer is $1,200, dividing by loaded miles gives $2.40 per mile. Dividing by total miles gives $2.00 per mile. Neither number is profit. Fuel, time and other costs still matter. Save this check, and make sure your comparison includes the miles before the load.",
"A $1,200 load does not mean $1,200 in profit. In this fictional example, suppose fuel is $400, tolls are $50 and allocated operating costs are $300. Subtracting those leaves $450 before any other costs or taxes that apply. Those are made-up inputs, not typical industry costs. Your own labor, maintenance, insurance, financing and other expenses may change the picture. Build a complete cost review before deciding. Save this checklist as a starting point.",
"The person at the dispatch desk still makes the call. ProfitLane's founder, Angel, has approximately eight years of trucking industry experience. His mission is to help dispatchers rather than replace them. The assistant is being developed to support a closer look at the numbers, while the dispatcher brings the context and makes the decision. That is the idea behind ProfitLane. What would useful AI assistance look like at your desk?",
"How much fuel does this fictional trip actually need? Start with 600 total miles. At an assumed six miles per gallon, that is 100 gallons. At an assumed four dollars per gallon, estimated fuel cost is $400. Change the MPG or the price and your estimate changes. This is a simplified example, not a fuel quote or a prediction for your truck. Review actual conditions and your own assumptions. Check the inputs before you use the result.",
"Would you accept a load because a screen says 76? This is a concept mockup, not a live ProfitLane feature. A proposed rating from one to one hundred could summarize inputs such as deadhead, fuel and mileage. But the scoring method has not been validated. Seventy-six here is just a made-up visual example, not a recommendation. You would still need the inputs, the missing information and your own judgment. What would you need to see behind a score?",
"Before you counter, what do you still need to know? In a fictional rate conversation, I would first ask: Can you confirm pickup and delivery appointment times? What accessorial terms apply, and how are they documented? Are there any other load requirements I should review? Then I can explain a counteroffer using accurate trip facts. No script guarantees a better rate. Save the questions and adapt them to your own process and agreements.",
"Both loads pay $1,200. Would you review them the same way? In this fictional example, Load A has 500 loaded miles and 100 deadhead miles: 600 total. That is two dollars of revenue per total mile. Load B has 500 loaded miles and 200 deadhead miles: 700 total. That is about a dollar seventy-one per total mile. Neither figure is profit. Costs, timing and the next move still need review. Save this comparison as one part of your checklist.",
"Here is the idea—not a live product demo. This paper prototype shows a proposed ProfitLane workflow. First, enter fictional load details, including loaded miles, deadhead and fuel assumptions. Next, review the information and identify anything missing. A proposed summary could explain the inputs behind a rating. Then the dispatcher reviews costs, timing and context before making a decision. The interface and features are still in development; this is not a validated scoring system. Which step needs more clarity?",
"What should AI leave to the dispatcher? A tool can help organize information, but relationships, unusual conditions and final decisions need human judgment. ProfitLane is in development as an assistant to dispatchers. The purpose is to support a closer look at the numbers, not to promise a better rate or make the call for you. Made for dispatchers by dispatchers. Tell us one part of your review you would always want to handle yourself."
]
visuals=[
('0–3s: Angel or team presenter at a parked desk. 3–20s: fictional input cards beside the presenter. 20–35s: approved logo and mission.','AI assistance • In development | Your judgment stays in control | Follow for load-review tips'),
('0–3s: empty route arrow. 3–12s: write 100 + 500 = 600. 12–25s: show $1,200 ÷ 500 and $1,200 ÷ 600. 25–40s: cost checklist.','Fictional example | 100 deadhead + 500 loaded = 600 total | $2.40/loaded mile vs $2.00/total mile | Revenue ≠ profit'),
('0–3s: $1,200 revenue card. 3–25s: subtract each labeled expense. 25–40s: show remaining review items.','Fictional inputs—not typical costs | $1,200 − $400 − $50 − $300 = $450 | Before other applicable costs and taxes'),
('0–3s: founder portrait or approved team intro. 3–22s: interview at a desk. 22–35s: mission over approved logo.','Angel • Founder | Approximately 8 years in trucking* | AI assists. Dispatcher decides. | *Confirm founder wording before recording'),
('0–3s: calculator and total-mile card. 3–15s: 600 ÷ 6 = 100 gallons. 15–27s: 100 × $4 = $400. 27–40s: assumptions checklist.','Fictional example | 600 miles ÷ 6 MPG = 100 gal | 100 gal × $4 = $400 estimated fuel | Assumptions change results'),
('0–3s: paper score card. 3–23s: point to fictional input labels. 23–40s: replace focus on the number with questions. Keep concept label visible throughout.','Concept mockup • In development | 76/100: arbitrary illustration | Proposed scoring is unvalidated | Review inputs. You decide.'),
('0–3s: presenter with question cards. 3–26s: team member plays broker, no real company shown. 26–40s: three-question recap.','Fictional role-play | Confirm appointment times | Clarify accessorial terms | Verify other requirements | No guaranteed rate outcome'),
('0–3s: two $1,200 cards. 3–20s: animate total-mile sums. 20–35s: show division side by side. 35–45s: costs/time prompt.','Fictional loads | A: $1,200 ÷ 600 = $2.00/mi | B: $1,200 ÷ 700 ≈ $1.71/mi | Revenue per total mile—not profit'),
('0–3s: visible paper prototype. 3–15s: point to input fields. 15–28s: flag unknown inputs. 28–45s: proposed explanation and human review. Keep concept label visible throughout.','Concept mockup • In development | 1. Inputs 2. Review 3. Explanation 4. Your decision | Proposed score is unvalidated'),
('0–3s: presenter asks the question. 3–25s: three cards: context, relationships, judgment. 25–40s: mission and comment prompt.','In development | Context • Relationships • Judgment | Made for dispatchers by dispatchers.')]
posts=[x for x in calendar if x['activity']=='Publish']
scripts=[]
for i,p in enumerate(posts[:10]):
 scripts.append(dict(number=i+1,day=p['day'],date=p['date'],title=p['title'],hook=p['hook'],length='35–45 seconds' if i in (1,2,4,5,6,7,8,9) else '30–40 seconds',script=spoken[i],scenes=visuals[i][0],text=visuals[i][1],caption=p['caption'],hashtags=p['hashtags'],cta=p['cta']))
data=dict(calendar=calendar,scripts=scripts)
(ROOT/'content.js').write_text('window.PROFITLANE_CONTENT = '+json.dumps(data,ensure_ascii=False,indent=2)+';\n')
with (ROOT/'content-calendar.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(calendar[0])); w.writeheader(); w.writerows(calendar)
intro='# 30-day TikTok content calendar\n\nSuggested window: November 9–December 8, 2026. Publish three times weekly: 13 publishing slots. The other 17 days are production, response and review days with reserve concepts, not extra daily posts. All topics are fictional plans; dates can be shifted. Suggested publishing test: 6 p.m. in the audience’s primary time zone; validate through account analytics. See the CSV for spreadsheet use.\n\n'
for p in calendar:
 intro+=f"## Day {p['day']} · {p['date']} · {p['activity']}\n\n"
 for k,label in [('title','Video topic / reserve idea'),('category','Pillar'),('hook','Hook'),('format','Format'),('message','Main message'),('caption','Caption'),('hashtags','Hashtags'),('cta','CTA')]: intro+=f"- **{label}:** {p[k]}\n"
 if p['activity']!='Publish': intro+='- **Work today:** Prepare this reserve concept, respond to relevant comments, or review equal-window results. Do not publish an extra video by default.\n'
 intro+='\n'
(ROOT/'content-calendar.md').write_text(intro)
s='# First ten scheduled TikTok videos\n\nRecord vertical 9:16, stationary and safely away from driving. Use fictional data only, approved brand assets, clear audio and checked captions. Lengths are targets; rehearse and adjust pauses. Opening hooks are the first 2–3 seconds and are included in the complete scripts below. Speaker may be Angel or an identified team presenter. Obtain Angel’s confirmation of founder details before filming video 4; do not present a team member as Angel. Product concepts are labeled throughout and do not demonstrate a live product.\n\n'
for p in scripts:
 s+=f"## {p['number']}. {p['title']}\n\n**Scheduled:** Day {p['day']} · {p['date']}\n\n**Length:** {p['length']}\n\n**Opening hook (2–3 seconds):** {p['hook']}\n\n**Full voiceover / speaking script:**\n\n{p['script']}\n\n**Scenes and visuals:** {p['scenes']}\n\n**On-screen text:** {p['text']}\n\n**Caption:** {p['caption']}\n\n**Hashtags:** {p['hashtags']}\n\n**CTA:** {p['cta']}\n\n"
(ROOT/'video-scripts.md').write_text(s)
print('Created 30 calendar entries and 10 complete scripts.')
